head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > gotoLastYear]<br/>Calendar 컴포넌트의 달력을 1년 전으로 이동합니다.",
    "validation" : [
        "gotoLastYear() 메소드 호출 시 Calendar 컴포넌트의 달력이 1년 전으로 이동합니다.",
        "달력이 이동될때 선택일의 변경 여부는 dateMoveFixed 속성값에 따라 달라집니다.",
        "달력 이동 후 getValue() 메소드의 반환값이 이동 전과 다르면 onchange 이벤트가 발생합니다.",
        "gotoLastYear() 메소드는 minYear/maxYear 속성값의 영향을 받지 않습니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        dateMoveFixed : con_dateMoveFixed.getText(),
        minYear : con_minYear.getValue(),
        maxYear : con_maxYear.getValue()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange"]);

    await $c.gcm.createBasicCalendar(cList, eList);
    // createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 선택일: 2025-11-11
}



// gotoLastYear() 호출 → 1년 전으로 이동 + dateMoveFixed 동작 비교
// validation:
//  - gotoLastYear 호출 시 1년 전으로 이동 (getValue 변화로 확인)
//  - dateMoveFixed 에 따라 선택일 변경 여부 결정 (전/후 getValue 비교)
//  - minYear/maxYear 영향 받지 않음 (minYear/maxYear 옵션 변경 후 재호출하여 확인)
scwin.btn_gotoLastYear_onclick = function (e) {
    let beforeValue = target1.getValue();
    target1.gotoLastYear();
    let afterValue = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue(
        "[gotoLastYear 호출 전 getValue()] '" + beforeValue + "'"
        + " / [gotoLastYear 호출 후 getValue()] '" + afterValue + "'"
    );
};



// 달력 이동 후 getValue() 반환값이 이동 전과 다르면 onchange 이벤트 발생
// @spec validation
scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onchange 발생] getValue() 반환값이 이동 전과 달라 onchange 핸들러 호출됨");
};
